public class RangesTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        int[] data = { 1, 3, 5, 7, 9, 10 };
        check("countWhere with an even-number lambda", 1, Ranges.countWhere(data, n -> n % 2 == 0));
        check("countWhere when nothing matches", 0, Ranges.countWhere(data, n -> n > 100));
        check("countWhere on empty array", 0, Ranges.countWhere(new int[0], n -> true));
        java.util.function.IntPredicate mid = Ranges.inRange(3, 7);
        check("inRange returns a predicate", true, mid != null);
        if (mid != null) {
            check("low bound is inclusive", true, mid.test(3));
            check("high bound is inclusive", true, mid.test(7));
            check("below the range", false, mid.test(2));
            check("above the range", false, mid.test(8));
            check("countWhere with inRange(3, 7)", 3, Ranges.countWhere(data, mid));
            check("composition with negate()", 3, Ranges.countWhere(data, mid.negate()));
            check("composition with and()", 2, Ranges.countWhere(data, mid.and(n -> n > 3)));
        } else {
            check("low bound is inclusive", true, "skipped -- inRange returned null");
            check("high bound is inclusive", true, "skipped -- inRange returned null");
            check("countWhere with inRange(3, 7)", 3, "skipped -- inRange returned null");
            check("composition with negate()", 3, "skipped -- inRange returned null");
            check("composition with and()", 2, "skipped -- inRange returned null");
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

