public class Ranges {

    public static java.util.function.IntPredicate inRange(int lo, int hi) {
        return v -> lo <= v && v <= hi;
    }

    public static int countWhere(int[] values, java.util.function.IntPredicate p) {
        int count = 0;
        for (int v : values) {
            if (p.test(v)) {
                count++;
            }
        }
        return count;
    }
}
